tool_input.command:
# Read the remaining close JSONs that I haven't extracted yet
for f in /home/usain/Dynamic-Agentic-Engineering-OS/.gov-runtime/scratch/orchestrator/log/close-W1-{30G2,15H,15H2,30J,30K,38L,30-final,38-final,38M,31b,31b-second,02R9,41R,42}.json; do
  echo "=== $(basename "$f") ==="
  python3 -I -c "
import json,sys
d=json.load(open(sys.argv[1]))
ok=d.get('ok')
err=d.get('error',{})
code=err.get('code','')
msg=err.get('message','')[:300]
det=err.get('details',{})
findings=det.get('findings',[])
accepted=det.get('accepted_reds',[])
load=det.get('load_sensitive',[])
red=det.get('red_findings',[])
gov_check=det.get('gov_check',{})
duration=d.get('duration','')
timing=d.get('timing',{})
ticket=det.get('ticket','') or d.get('ticket','')
print(f'ok={ok}  code={code}  ticket={ticket}')
print(f'msg={msg}')
print(f'findings_count={len(findings)}  accepted_reds_count={len(accepted)}  load_sensitive_count={len(load)}  red_findings_count={len(red)}')
if duration: print(f'duration={duration}')
if timing: print(f'timing={timing}')
for fi in findings[:5]:
  if isinstance(fi,str): print(f'  finding: {fi[:250]}')
  else: print(f'  finding: {json.dumps(fi)[:250]}')
for r in red[:3]:
  if isinstance(r,dict): print(f'  red: code={r.get(\"code\",\"\")} test={r.get(\"test\",\"\")[:150]}')
for a in accepted[:3]:
  if isinstance(a,dict): print(f'  accepted_red: test={a.get(\"test\",\"\")[:120]} decision={a.get(\"decision\",\"\")}')
for l in load[:3]:
  if isinstance(l,dict): print(f'  load_sensitive: test={l.get(\"test\",\"\")[:120]} result={l.get(\"result\",\"\")}')
print()
" "$f" 2>&1
done
